package net.officefloor.hq.app.sheet;

import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import java.util.Map;
import org.springframework.context.annotation.Configuration;
import org.springframework.http.HttpMethod;
import org.springframework.web.servlet.HandlerInterceptor;
import org.springframework.web.servlet.HandlerMapping;
import org.springframework.web.servlet.config.annotation.InterceptorRegistry;
import org.springframework.web.servlet.config.annotation.WebMvcConfigurer;

/** Refuse every change asked of an archived sheet: any request on it other than a read, before it reaches its
 * handler, so it writes nothing and records nothing. Loading the sheet is a read. Opening or settling claims
 * together goes through, so that each claim is refused on its own and counted as refused. */
@Configuration
public class ArchiveGuard implements HandlerInterceptor, WebMvcConfigurer {

    private final ArchiveService archives;

    public ArchiveGuard(ArchiveService archives) {
        this.archives = archives;
    }

    @Override
    public void addInterceptors(InterceptorRegistry registry) {
        registry.addInterceptor(this).addPathPatterns("/api/sheets/{sheet}/**").excludePathPatterns("/api/sheets/load",
                "/api/sheets/{sheet}/claims/open", "/api/sheets/{sheet}/claims/settle");
    }

    @Override
    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) {
        if (HttpMethod.GET.matches(request.getMethod()) || HttpMethod.HEAD.matches(request.getMethod())
                || HttpMethod.OPTIONS.matches(request.getMethod())) {
            return true;
        }
        @SuppressWarnings("unchecked")
        Map<String, String> vars = (Map<String, String>) request
                .getAttribute(HandlerMapping.URI_TEMPLATE_VARIABLES_ATTRIBUTE);
        String sheetId = vars == null ? null : vars.getOrDefault("sheetId", vars.get("id"));
        if (sheetId != null) {
            archives.requireNotArchived(sheetId);
        }
        return true;
    }
}
package net.officefloor.hq.app.sheet;

import java.time.LocalDate;
import net.officefloor.hq.app.period.PeriodService;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.rollup.RollupService.Snapshot;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** Changing a sheet's today, and what follows from it. */
@Service
public class TodayService {

    private final SheetRepository sheets;
    private final SheetService sheetService;
    private final PeriodService periods;
    private final RollupService rollup;

    public TodayService(SheetRepository sheets, SheetService sheetService, PeriodService periods,
            RollupService rollup) {
        this.sheets = sheets;
        this.sheetService = sheetService;
        this.periods = periods;
        this.rollup = rollup;
    }

    /** Change the sheet's today; it writes no line of its own. Every open period past the sheet's grace days is
     * then closed, each writing its line, and then the figures the change moves are written. */
    @Transactional
    public Sheet setToday(String user, String id, LocalDate today) {
        sheetService.lock(id);
        Sheet sheet = sheets.findById(id)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such sheet."));
        Snapshot before = rollup.snapshot(id);
        sheet.setToday(today);
        sheets.flush();
        periods.closeLapsed(user, id);
        rollup.recordChanges(user, id, before);
        return sheet;
    }
}
package net.officefloor.hq.app.sheet;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.setting.SettingService;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** Archiving a sheet, and whether a sheet is archived. */
@Service
public class ArchiveService {

    private final SheetRepository sheets;
    private final SheetService sheetService;
    private final SettingService settings;
    private final Audit audit;

    public ArchiveService(SheetRepository sheets, SheetService sheetService, SettingService settings, Audit audit) {
        this.sheets = sheets;
        this.sheetService = sheetService;
        this.settings = settings;
        this.audit = audit;
    }

    /** Archive the sheet: only a steward may, and only once. */
    @Transactional
    public Sheet archive(String user, String id) {
        sheetService.lock(id);
        Sheet sheet = sheets.findById(id)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such sheet."));
        settings.requireSteward(id, user);
        requireNotArchived(sheet);
        sheet.archive();
        audit.recordOnCommit("SHEET_ARCHIVED sheet=" + id + " by=" + user);
        return sheet;
    }

    /** Refuse any change to an archived sheet; a sheet not in the store is not archived. */
    @Transactional(readOnly = true)
    public void requireNotArchived(String id) {
        if (sheets.findById(id).map(Sheet::isArchived).orElse(false)) {
            throw archived();
        }
    }

    private static void requireNotArchived(Sheet sheet) {
        if (sheet.isArchived()) {
            throw archived();
        }
    }

    private static ResponseStatusException archived() {
        return new ResponseStatusException(HttpStatus.FORBIDDEN, "The sheet is archived.");
    }
}
package net.officefloor.hq.app.sheet;

import java.time.Instant;
import java.time.LocalDate;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.http.HttpStatus;

@Service
public class SheetService {

    private final SheetRepository sheets;
    public SheetService(SheetRepository sheets) {
        this.sheets = sheets;
    }

    /** The sheet with this id, re-read from the store; a sheet never loaded before starts empty. */
    @Transactional
    public Sheet load(String id, String user) {
        return sheets.findById(id).orElseGet(() -> {
            try {
                return sheets.saveAndFlush(new Sheet(id, user, Instant.now()));
            } catch (DataIntegrityViolationException e) {
                // Another user created it at the same moment.
                return sheets.findById(id).orElseThrow(() -> e);
            }
        });
    }

    /**
     * The sheet's today. Every feature that decides by the date, or defaults a date, asks this
     * rather than the real clock.
     */
    @Transactional(readOnly = true)
    public LocalDate today(String id) {
        return find(id).getToday();
    }

    /**
     * Give out the sheet's next claim number. The sheet stays locked until the calling transaction
     * ends, so claims opened at the same moment get different numbers, and a rolled back
     * transaction gives its number back.
     */
    @Transactional
    public int nextClaimNumber(String id) {
        if (sheets.incrementClaimNumber(id) == 0) {
            throw new ResponseStatusException(HttpStatus.NOT_FOUND, "No such sheet.");
        }
        return sheets.lastClaimNumber(id);
    }

    /** Whether the sheet is archived, so that every change to it is refused. */
    @Transactional(readOnly = true)
    public boolean isArchived(String id) {
        return find(id).isArchived();
    }

    /** Whether a claim opened now on the sheet is numbered within its period, not sheet-wide. */
    @Transactional(readOnly = true)
    public boolean numbersByPeriod(String id) {
        return find(id).numbersByPeriod();
    }

    /** Lock the sheet until the calling transaction ends, so changes that must not race take turns. */
    @Transactional
    public void lock(String id) {
        sheets.findLocked(id)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such sheet."));
    }

    private Sheet find(String id) {
        return sheets.findById(id)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such sheet."));
    }
}

