70	        requireNotRetired(person, date != null ? date : today);
71	        requireOpenPeriod(sheetId, date != null ? date : today);
72	        String corrected = correctedBy(sheetId, personId, amount, corrects);
73	        Snapshot before = rollup.snapshot(sheetId);
74	        LocalDate dated = date != null ? date : today;
75	        LocalDate dueBy = dueBy(sheetId, person, dated);
76	        Claim fresh = new Claim(sheetId, personId, amount, dated, dueBy, noteOf(note));
77	        fresh.setCorrects(corrected);
78	        Claim claim = claims.saveAndFlush(fresh);
79	        logStatus(user, today, claim, person);
80	        claims.flush();
81	        audit.recordOnCommit(entry("CLAIM_ADDED", user, person, claim));
82	        rollup.recordChanges(user, sheetId, before);
83	        return claim;
84	    }
