87	     * in a closed period, or that would be, is refused, as is a correction that does not name a settled claim of
88	     * the same person. */
89	    @Transactional
90	    public Claim update(String user, String sheetId, Long id, BigDecimal amount, LocalDate date, String note,
91	            String corrects) {
92	        LocalDate today = sheets.today(sheetId);
93	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
94	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
95	        if (claim.getStatus() != ClaimStatus.DRAFT) {
96	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a draft claim can be edited.");
97	        }
98	        requireOpenPeriod(sheetId, claim.getDate());
99	        requireOpenPeriod(sheetId, date != null ? date : today);
100	        requireNotRetired(requirePerson(sheetId, claim.getPersonId()), date != null ? date : today);
101	        String corrected = correctedBy(sheetId, claim.getPersonId(), amount, corrects);
102	        Snapshot before = rollup.snapshot(sheetId);
