104	        claim.setCorrects(corrected);
105	        claim.setDate(date != null ? date : today);
106	        claim.setNote(noteOf(note));
107	        claims.flush();
108	        audit.recordOnCommit(entry("CLAIM_EDITED", user, requirePerson(sheetId, claim.getPersonId()), claim));
109	        rollup.recordChanges(user, sheetId, before);
