113	    /** Move a claim to another status; a change its status does not allow, or of a claim dated in a closed
114	     * period, is refused. A settle by a clerk of a claim whose due is above the clerk limit sends it PENDING a
115	     * steward instead. */
116	    @Transactional
117	    public Claim changeStatus(String user, String sheetId, Long id, ClaimStatus next) {
118	        sheets.today(sheetId); // the sheet must exist
119	        // Locking the sheet before taking the number opens claims one at a time; a refused open rolls back
120	        // and gives the number back.
121	        if (next == ClaimStatus.OPEN) {
122	            sheets.lock(sheetId);
123	        }
124	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
125	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
126	        String number = next == ClaimStatus.OPEN ? nextNumber(sheetId, claim) : null;
127	        requireOpenPeriod(sheetId, claim.getDate());
128	        if (!claim.getStatus().canBecome(next)) {
129	            throw new ResponseStatusException(HttpStatus.CONFLICT,
130	                    "A " + claim.getStatus() + " claim cannot become " + next + ".");
131	        }
132	        // Only a role the sheet's permission matrix allows may open, settle or void a claim.
133	        settings.requirePermitted(sheetId, user, PERMISSIONS.get(next));
134	        // A deferred claim cannot be settled until the sheet's today reaches the date it is deferred until.
135	        if (next == ClaimStatus.SETTLED && claim.deferredOn(sheets.today(sheetId))) {
136	            throw new ResponseStatusException(HttpStatus.CONFLICT,
137	                    "The claim is deferred until " + claim.getDeferredUntil() + ".");
138	        }
139	        // Four eyes: whoever opened a claim cannot also settle it.
140	        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
141	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "The user who opened a claim cannot settle it.");
142	        }
143	        Person person = requirePerson(sheetId, claim.getPersonId());
144	        BigDecimal due = rollup.dueOf(claim, person);
145	        // A claim whose due is above the proof threshold in force on its date needs a proof before it is settled,
146	        // whoever settles it, so it never goes PENDING without one.
147	        if (next == ClaimStatus.SETTLED) {
148	            settings.requireProof(sheetId, claim.getDate(), due, claim.getProofs());
149	        }
150	        // A clerk settles only a claim whose due is within the sheet's clerk limit; above it, a steward must
151	        // approve it.
152	        if (next == ClaimStatus.SETTLED && !settings.maySettle(sheetId, user, due)) {
153	            next = ClaimStatus.PENDING;
154	        }
155	        Snapshot before = rollup.snapshot(sheetId);
156	        claim.setStatus(next);
157	        if (next == ClaimStatus.OPEN) {
158	            claim.setNumber(number);
159	            claim.setOpenedBy(user);
160	        }
161	        // A voided claim's line carries the number it had.
162	        String entry = entry(EVENTS.get(next), user, person, claim);
163	        if (next == ClaimStatus.SETTLED) {
164	            // Settling fixes the due at the figure the claim has: the one its last statement bound it to, else
165	            // the rate its grade has on its date; with no figure it stays live. The late charge it has (taken
166	            // while it is still OPEN) is frozen in.
167	            entry += settle(claim, due);
168	        }
169	        logStatus(user, sheets.today(sheetId), claim, person);
170	        claims.flush();
171	        audit.recordOnCommit(entry);
172	        if (next == ClaimStatus.SETTLED) {
173	            notifyWatchers(user, person, claim);
174	        }
175	        rollup.recordChanges(user, sheetId, before);
176	        return claim;
177	    }
