179	    /** A steward approves a PENDING claim: it is SETTLED at the due it has now, its live figure with any late
180	     * charge, frozen. The user who opened it cannot approve it, and one whose due is above the proof threshold
181	     * in force on its date cannot be approved while it has no proof. */
182	    @Transactional
183	    public Claim approve(String user, String sheetId, Long id) {
184	        Claim claim = requirePending(user, sheetId, id);
185	        if (user.equals(claim.getOpenedBy())) {
186	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "The user who opened a claim cannot approve it.");
187	        }
188	        Person person = requirePerson(sheetId, claim.getPersonId());
189	        Snapshot before = rollup.snapshot(sheetId);
190	        BigDecimal due = rollup.dueOf(claim, person);
191	        settings.requireProof(sheetId, claim.getDate(), due, claim.getProofs());
192	        claim.setStatus(ClaimStatus.SETTLED);
193	        String entry = entry("CLAIM_APPROVED", user, person, claim) + settle(claim, due);
194	        logStatus(user, sheets.today(sheetId), claim, person);
195	        claims.flush();
196	        audit.recordOnCommit(entry);
197	        notifyWatchers(user, person, claim);
198	        rollup.recordChanges(user, sheetId, before);
199	        return claim;
200	    }
