202	    /** A steward re-settles a SETTLED claim: it is frozen again at the figure it would have today as an OPEN
203	     * claim bound by no statement, at today's rates, grades, floor and late charge. Refused for anyone else, a
204	     * claim of any other status, or one dated in a closed period. */
205	    @Transactional
206	    public Claim resettle(String user, String sheetId, Long id) {
207	        sheets.today(sheetId); // the sheet must exist
208	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
209	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
210	        requireOpenPeriod(sheetId, claim.getDate());
211	        if (claim.getStatus() != ClaimStatus.SETTLED) {
212	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a SETTLED claim can be re-settled.");
213	        }
214	        settings.requireSteward(sheetId, user);
215	        Person person = requirePerson(sheetId, claim.getPersonId());
216	        Snapshot before = rollup.snapshot(sheetId);
217	        BigDecimal old = rollup.dueOf(claim, person);
218	        BigDecimal now = rollup.openDueOf(claim, person);
219	        claim.setSettledDue(now);
220	        logStatus(user, sheets.today(sheetId), claim, person);
221	        claims.flush();
222	        audit.recordOnCommit(entry("CLAIM_RESETTLED", user, person, claim) + " old=" + figure(old) + " new="
223	                + figure(now));
224	        notifyWatchers(user, person, claim);
225	        rollup.recordChanges(user, sheetId, before);
226	        return claim;
227	    }
