242	    /** Defer an OPEN claim until a date after the sheet's today: until then it counts in no total, is not overdue,
243	     * cannot be settled and is left unbound by a statement. A claim that is not OPEN, a date not after today, or
244	     * a claim dated in a closed period, is refused. */
245	    @Transactional
246	    public Claim defer(String user, String sheetId, Long id, LocalDate until) {
247	        LocalDate today = sheets.today(sheetId);
248	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
249	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
250	        requireOpenPeriod(sheetId, claim.getDate());
251	        if (claim.getStatus() != ClaimStatus.OPEN) {
252	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only an OPEN claim can be deferred.");
253	        }
254	        if (!until.isAfter(today)) {
255	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A claim is deferred to a date after today.");
256	        }
257	        Person person = requirePerson(sheetId, claim.getPersonId());
258	        Snapshot before = rollup.snapshot(sheetId);
259	        claim.setDeferredUntil(until);
260	        claims.flush();
261	        audit.recordOnCommit(entry("CLAIM_DEFERRED", user, person, claim) + " until=" + until);
262	        rollup.recordChanges(user, sheetId, before);
263	        return claim;
264	    }
