266	    /** Split an amount off an OPEN claim: more than 0.00 and less than its amount. The claim keeps the rest and
267	     * loses any figure a statement bound it to; a new OPEN claim of the amount split off, with the same date and
268	     * note, takes the next number, is opened by the user, has its due-by fixed now from the terms in force on the
269	     * date, and names the claim it was split from. A claim that is not OPEN (PENDING, settled, ...), is deferred,
270	     * or is dated in a closed period, is refused. */
271	    @Transactional
272	    public Split split(String user, String sheetId, Long id, BigDecimal amount) {
273	        LocalDate today = sheets.today(sheetId);
274	        // Locking the sheet before taking the number numbers claims one at a time; a refused split rolls back and
275	        // gives the number back.
276	        sheets.lock(sheetId);
277	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
278	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
279	        requireOpenPeriod(sheetId, claim.getDate());
280	        if (claim.getStatus() != ClaimStatus.OPEN) {
281	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only an OPEN claim can be split.");
282	        }
283	        if (claim.deferredOn(today)) {
284	            throw new ResponseStatusException(HttpStatus.CONFLICT,
285	                    "The claim is deferred until " + claim.getDeferredUntil() + ".");
286	        }
287	        if (amount.signum() <= 0 || amount.compareTo(claim.getAmount()) >= 0) {
288	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
289	                    "The amount split off is more than 0.00 and less than the claim's amount.");
290	        }
291	        Person person = requirePerson(sheetId, claim.getPersonId());
292	        Snapshot before = rollup.snapshot(sheetId);
293	        claim.setAmount(claim.getAmount().subtract(amount));
294	        claim.unbind();
295	        LocalDate dated = claim.getDate();
296	        LocalDate dueBy = dueBy(sheetId, person, dated);
297	        Claim fresh = new Claim(sheetId, person.getId(), amount, dated, dueBy, claim.getNote());
298	        fresh.setSplitFrom(claim.getNumber());
299	        fresh.setStatus(ClaimStatus.OPEN);
300	        fresh.setNumber(nextNumber(sheetId, fresh));
301	        fresh.setOpenedBy(user);
302	        Claim split = claims.saveAndFlush(fresh);
303	        logStatus(user, today, split, person);
304	        claims.flush();
305	        audit.recordOnCommit(entry("CLAIM_SPLIT", user, person, claim) + " into=" + split.getNumber());
306	        audit.recordOnCommit(entry("CLAIM_OPENED", user, person, split));
307	        rollup.recordChanges(user, sheetId, before);
308	        return new Split(claim, split);
309	    }
