348	    /** A user whose role may reassign (a steward by the standing rule) moves a DRAFT, OPEN or PENDING claim to another person on the sheet. It keeps its number and
349	     * date but loses any figure a statement bound it to: it is live again until its new person's next statement.
350	     * One dated in a closed period, a correction (which names a settled claim of its own person), or one dated
351	     * after its new person is retired, is refused. */
352	    @Transactional
353	    public Claim reassign(String user, String sheetId, Long id, Long toPersonId) {
354	        sheets.today(sheetId); // the sheet must exist
355	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
356	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
357	        settings.requirePermitted(sheetId, user, Permission.REASSIGN);
358	        requireOpenPeriod(sheetId, claim.getDate());
359	        if (claim.getStatus() != ClaimStatus.DRAFT && !claim.getStatus().isOpen()) {
360	            throw new ResponseStatusException(HttpStatus.CONFLICT,
361	                    "A " + claim.getStatus() + " claim cannot be moved.");
362	        }
363	        if (claim.isCorrection()) {
364	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A correction cannot be moved.");
365	        }
366	        Person from = requirePerson(sheetId, claim.getPersonId());
367	        Person to = requirePerson(sheetId, toPersonId);
368	        if (from.getId().equals(to.getId())) {
369	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The claim is already that person's.");
370	        }
371	        if (to.retiredOn(claim.getDate())) {
372	            throw new ResponseStatusException(HttpStatus.GONE,
373	                    to.getName() + " is retired from " + to.getRetiredFrom() + ".");
374	        }
375	        Snapshot before = rollup.snapshot(sheetId);
376	        claim.setPersonId(to.getId());
377	        claim.unbind();
378	        claims.flush();
379	        audit.recordOnCommit(entry("CLAIM_REASSIGNED", user, to, claim) + " from=" + from.getName() + " to="
380	                + to.getName());
381	        rollup.recordChanges(user, sheetId, before);
382	        return claim;
383	    }
