422	    /** Settle the given claims of the sheet one at a time, in list order, each as {@link #changeStatus} would
423	     * settle it on its own: one a clerk sends PENDING counts as settled; one that cannot be settled (or is not on
424	     * the sheet) is refused and left as it is. */
425	    public OpenedAll settleAll(String user, String sheetId, List<Long> ids) {
426	        return changeAll(user, sheetId, ids, ClaimStatus.SETTLED);
427	    }
