429	    /** Move the given claims to a status one at a time, in list order: people in the order they were added, each
430	     * one's claims newest first, each in its own transaction; one that is refused is left as it is. */
431	    private OpenedAll changeAll(String user, String sheetId, List<Long> ids, ClaimStatus next) {
432	        Set<Long> wanted = new HashSet<>(ids);
433	        List<Claim> chosen = transaction.execute(status -> {
434	            sheets.today(sheetId); // the sheet must exist
435	            Map<Long, Integer> personOrder = new HashMap<>();
436	            for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
437	                personOrder.put(person.getId(), personOrder.size());
438	            }
439	            return claims.findBySheetIdOrderByIdDesc(sheetId).stream()
440	                    .filter(c -> wanted.contains(c.getId()))
441	                    .sorted(Comparator.comparing((Claim c) -> personOrder.getOrDefault(c.getPersonId(), Integer.MAX_VALUE)))
442	                    .toList();
443	        });
444	        List<Claim> changed = new ArrayList<>();
445	        if (settings.roleOf(sheetId, user) == Role.VIEWER || sheets.isArchived(sheetId)) {
446	            // A viewer, or anyone on an archived sheet, changes nothing: every claim is refused.
447	            return new OpenedAll(0, wanted.size(), changed);
448	        }
449	        for (Claim claim : chosen) {
450	            try {
451	                changed.add(transaction.execute(status -> changeStatus(user, sheetId, claim.getId(), next)));
452	            } catch (ResponseStatusException refused) {
453	                // Left as it is: its transaction rolled back, writing nothing.
454	            }
455	        }
456	        return new OpenedAll(changed.size(), wanted.size() - changed.size(), changed);
457	    }
