459	    /** The sequence a claim in no period is numbered in, with period numbering. */
460	    private static final String NO_PERIOD = "X";
461	
462	    /** The action of the permission matrix each status a claim is moved to takes. */
463	    private static final Map<ClaimStatus, Permission> PERMISSIONS = Map.of(
464	            ClaimStatus.OPEN, Permission.OPEN,
465	            ClaimStatus.SETTLED, Permission.SETTLE,
466	            ClaimStatus.VOID, Permission.VOID);
467	
468	    private static final Map<ClaimStatus, String> EVENTS = Map.of(
469	            ClaimStatus.OPEN, "CLAIM_OPENED",
470	            ClaimStatus.PENDING, "CLAIM_PENDING",
471	            ClaimStatus.SETTLED, "CLAIM_SETTLED",
472	            ClaimStatus.VOID, "CLAIM_VOIDED");
473	
474	    /** The figure a claim has now: what it was settled at, else what its person's last statement bound it to,
475	     * else what is due at the rate of the grade its person has on its date; none when that is n/a. */
476	    public BigDecimal figureOf(Claim claim, Person person) {
477	        return rollup.figureOf(claim, person);
478	    }
479	
480	    /** The number a claim opened now takes: the sheet's next number or, with period numbering in force, the next
481	     * in its period's own sequence, <period name>-<n>, or X-<n> for a claim in no period. */
482	    private String nextNumber(String sheetId, Claim claim) {
483	        if (!sheets.numbersByPeriod(sheetId)) {
484	            return String.valueOf(sheets.nextClaimNumber(sheetId));
485	        }
486	        String prefix = periods.periodOf(sheetId, claim.getDate()).map(Period::getName).orElse(NO_PERIOD) + "-";
487	        int last = 0;
488	        for (Claim other : claims.findBySheetIdOrderByIdDesc(sheetId)) {
489	            String number = other.getNumber();
490	            if (number != null && number.startsWith(prefix)) {
491	                String rest = number.substring(prefix.length());
492	                if (rest.matches("\\d{1,9}")) {
493	                    last = Math.max(last, Integer.parseInt(rest));
494	                }
495	            }
496	        }
497	        return prefix + (last + 1);
498	    }
