500	    /** The number a claim of this amount corrects: none unless the amount is negative, when it must name a
501	     * SETTLED claim of the same person, or the claim is refused. */
502	    private String correctedBy(String sheetId, Long personId, BigDecimal amount, String corrects) {
503	        if (amount.signum() >= 0) {
504	            return null;
505	        }
506	        String named = corrects == null ? null : corrects.trim();
507	        boolean settled = named != null && claims.findBySheetIdAndPersonId(sheetId, personId).stream()
508	                .anyMatch(c -> named.equals(c.getNumber()) && c.getStatus() == ClaimStatus.SETTLED);
509	        if (!settled) {
510	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
511	                    "A correction must name a settled claim of the same person.");
512	        }
513	        return named;
514	    }
