531	    /** The due-by fixed for a claim of the person dated {@code dated}: its date plus the person's own terms, else
532	     * the terms in force then for the grade the person has then, else the sheet's terms then. */
533	    private LocalDate dueBy(String sheetId, Person person, LocalDate dated) {
534	        Integer own = person.getTerms();
535	        return dated.plusDays(own != null ? own : settings.termsFor(sheetId, person.gradeOn(dated), dated));
536	    }
537	
538	    private Person requirePerson(String sheetId, Long personId) {
539	        return people.findByIdAndSheetId(personId, sheetId)
540	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
541	    }
542	
543	    /** The amount is written as the screen shows it, with two decimals; the date as yyyy-mm-dd; a
544	     * claim with a number ends with it. */
545	    private static String entry(String event, String user, Person person, Claim claim) {
546	        return event + " sheet=" + claim.getSheetId() + " by=" + user + " person=" + person.getName()
547	                + " amount=" + claim.getAmount().setScale(2).toPlainString() + " date=" + claim.getDate()
548	                + (claim.getNumber() != null ? " number=" + claim.getNumber() : "");
549	    }
550	
551	    private static String noteOf(String note) {
552	        return note == null ? "" : note.trim();
553	    }
554	}
