832	/** A claim's status. Only OPEN, PENDING and SETTLED claims count toward what is claimed and due. A PENDING claim
833	 * was settled by a clerk above the clerk limit and waits for a steward to approve it (SETTLED) or reject it
834	 * (OPEN again). */
835	public enum ClaimStatus {
836	    DRAFT, OPEN, PENDING, SETTLED, VOID;
837	
838	    /** Whether a claim in this status may be opened, settled (or sent PENDING) or voided to the given status. A
839	     * PENDING claim moves on only by a steward's approval or rejection, or by being voided. */
840	    public boolean canBecome(ClaimStatus next) {
841	        return switch (next) {
842	            case OPEN -> this == DRAFT;
843	            case PENDING, SETTLED -> this == OPEN;
844	            case VOID -> this == DRAFT || this == OPEN || this == PENDING;
845	            case DRAFT -> false;
846	        };
847	    }
848	
849	    /** Whether a claim in this status is still open: OPEN, or PENDING a steward. Such a claim goes overdue, bears
850	     * the late charge, and a hold takes it out of the totals. */
851	    public boolean isOpen() {
852	        return this == OPEN || this == PENDING;
853	    }
