445	import jakarta.servlet.http.HttpServletRequest;
446	import jakarta.servlet.http.HttpServletResponse;
447	import java.util.Map;
448	import org.springframework.context.annotation.Configuration;
449	import org.springframework.http.HttpMethod;
450	import org.springframework.http.HttpStatus;
451	import org.springframework.web.server.ResponseStatusException;
452	import org.springframework.web.servlet.HandlerInterceptor;
453	import org.springframework.web.servlet.HandlerMapping;
454	import org.springframework.web.servlet.config.annotation.InterceptorRegistry;
455	import org.springframework.web.servlet.config.annotation.WebMvcConfigurer;
456	
457	/** Refuse every change a viewer asks of a sheet: any request on a sheet other than a read, before it reaches its
458	 * handler, so it writes nothing and records nothing. Loading the sheet is a read. Opening or settling claims
459	 * together goes through, so that each claim is refused on its own and counted as refused. */
460	@Configuration
461	public class ViewerGuard implements HandlerInterceptor, WebMvcConfigurer {
462	
463	    private final SettingService settings;
464	
465	    public ViewerGuard(SettingService settings) {
466	        this.settings = settings;
467	    }
468	
469	    @Override
470	    public void addInterceptors(InterceptorRegistry registry) {
471	        registry.addInterceptor(this).addPathPatterns("/api/sheets/{sheet}/**").excludePathPatterns("/api/sheets/load",
472	                "/api/sheets/{sheet}/claims/open", "/api/sheets/{sheet}/claims/settle");
473	    }
474	
475	    @Override
476	    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) {
477	        if (HttpMethod.GET.matches(request.getMethod()) || HttpMethod.HEAD.matches(request.getMethod())
478	                || HttpMethod.OPTIONS.matches(request.getMethod())) {
479	            return true;
480	        }
481	        String user = request.getHeader("X-User");
482	        @SuppressWarnings("unchecked")
483	        Map<String, String> vars = (Map<String, String>) request
484	                .getAttribute(HandlerMapping.URI_TEMPLATE_VARIABLES_ATTRIBUTE);
485	        String sheetId = vars == null ? null : vars.getOrDefault("sheetId", vars.get("id"));
486	        if (user != null && sheetId != null && settings.roleOf(sheetId, user.trim()) == Role.VIEWER) {
487	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "A viewer cannot change anything.");
488	        }
489	        return true;
490	    }
491	}
