603	     * line is read first; it is one change, so one line refused (here or by the claim form's rules) adds none.
604	     * Blank lines are skipped; a box with no line is refused. */
605	    @Transactional
606	    public List<Claim> paste(String user, String sheetId, String text) {
607	        List<Line> lines = new ArrayList<>();
608	        String[] raw = text.split("\\r?\\n");
609	        for (int i = 0; i < raw.length; i++) {
610	            if (!raw[i].isBlank()) {
611	                lines.add(read(sheetId, raw[i], i + 1));
612	            }
613	        }
614	        if (lines.isEmpty()) {
615	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Paste at least one line.");
616	        }
617	        List<Claim> added = new ArrayList<>();
618	        for (Line line : lines) {
619	            added.add(claims.add(user, sheetId, line.person().getId(), line.amount(), line.date(), line.note(), null));
620	        }
621	        return added;
622	    }
623	
624	    private Line read(String sheetId, String line, int number) {
625	        String[] fields = line.split(",", 4);
626	        if (fields.length < 2) {
627	            throw refused(number, "needs a name and an amount.");
628	        }
629	        String name = fields[0].trim();
630	        Person person = name.isEmpty() ? null : people.findByName(sheetId, name).orElse(null);
631	        if (person == null) {
632	            throw refused(number, "names no one on the sheet.");
633	        }
634	        String amount = fields[1].trim();
635	        if (!amount.matches(AMOUNT)) {
636	            throw refused(number, "needs an amount with up to two decimals.");
637	        }
638	        LocalDate date = null;
639	        if (fields.length > 2 && !fields[2].isBlank()) {
640	            try {
641	                date = LocalDate.parse(fields[2].trim());
642	            } catch (DateTimeParseException e) {
643	                throw refused(number, "needs a date as yyyy-mm-dd, or none.");
644	            }
645	        }
646	        String note = fields.length > 3 ? fields[3] : "";
647	        if (note.length() > NOTE_MAX) {
648	            throw refused(number, "has a note longer than " + NOTE_MAX + " characters.");
649	        }
650	        return new Line(person, new BigDecimal(amount), date, note);
651	    }
652	
653	    private static ResponseStatusException refused(int number, String why) {
654	        return new ResponseStatusException(HttpStatus.BAD_REQUEST, "Line " + number + " " + why);
655	    }
656	}
