  /** The sheet's periods by from-date. */
  protected readonly periods = signal<Period[]>([]);
  /** Each period's due-total for each person, by period id then person id: the sum of the dues, as shown now,
   * of the person's claims dated in it that count by the status they had at the end of its last day (n/a ones
   * skipped), 0.00 with none; a closed period's are the ones
   * fixed when it closed, 0.00 for a person who had none then. */
  protected readonly personPeriodDueTotals = computed(() => {
    const byId = new Map(this.people().map((p) => [p.id, p]));
    const dues = new Map<number, Map<number, string[]>>();
    for (const c of this.claims()) {
      const period = periodOf(this.periods(), c.date);
      const person = byId.get(c.personId);
      if (!period || period.closed || !person || !this.countsAt(c, period.to)) continue;
      const due = this.claimDue(c, person);
      if (due === NO_RATE) continue;
      const byPerson = dues.get(period.id) ?? new Map<number, string[]>();
      byPerson.set(person.id, [...(byPerson.get(person.id) ?? []), due]);
      dues.set(period.id, byPerson);
    }
    return new Map(
      this.periods().map((pd) => [
        pd.id,
        new Map(
          this.people().map((p) => [
            p.id,
            pd.closed
              ? (pd.personTotals?.[p.id] ?? '0.00')
              : sumAmounts(dues.get(pd.id)?.get(p.id) ?? []),
          ]),
        ),
      ]),
    );
  });
  /** Each period's due-total, by id: the sum of the people's due-totals for it. */
  protected readonly periodDueTotals = computed(
    () => new Map([...this.personPeriodDueTotals()].map(([id, byPerson]) => [id, sumAmounts([...byPerson.values()])])),
  );

  /** The sheet's due-total: the people's due-totals (n/a ones skipped) added up, trimmed of the highest and lowest. */
  protected readonly dueTotal = computed(() =>
    trimmedSum(this.people().map((p) => this.personDueTotal(p)).filter((d) => d !== NO_RATE)),
  );
  /** Per grade, the people not retired who have it on the sheet's today and their due-totals added up (n/a
   * ones skipped). */
  protected readonly gradeSummary = computed<GradeSummary[]>(() =>
    this.grades.map((grade) => {
      const on = this.people().filter((p) => !p.retiredFrom && this.gradeToday(p) === grade);
      const dueTotal = sumAmounts(on.map((p) => this.personDueTotal(p)).filter((d) => d !== NO_RATE));
      return { grade, count: on.length, dueTotal };
    }),
  );
  /** How many of the sheet's claims have each status. */
  protected readonly statusCounts = computed(() => {
    const by = new Map<string, number>();
    for (const c of this.claims()) by.set(c.status, (by.get(c.status) ?? 0) + 1);
    return by;
  });
  /** How many of the sheet's claims that count are overdue, and the sum of their dues (n/a ones skipped). */
  protected readonly overdueCount = computed(() =>
    this.people().reduce((n, p) => n + this.overdueOf(p).length, 0),
  );
  /** The sheet's overdue-total: the people's overdue-totals added up, trimmed of the highest and lowest. */
  protected readonly overdueTotal = computed(() => trimmedSum(this.people().map((p) => this.overdueTotalOf(p))));
  /** The ids of the claims selected to open together. */
  protected readonly selectedClaims = signal<ReadonlySet<number>>(new Set());
  }

  protected claimsOf(personId: number): Claim[] {
    return this.claimsByPerson().get(personId) ?? [];
  }

  protected claimed(personId: number): string {
    return sumAmounts(this.claimsOf(personId).filter((c) => this.countsLive(c)).map((c) => c.amount));
  }

  /** The grade the person has in force on the sheet's today. */
  protected gradeToday(person: Person): Grade {
    const today = this.session.today();
    return (today !== null ? gradeOn(person.grades, today) : undefined) ?? person.grade;
  }

  /** What is due on a claim of the person's, at the grade they have on the claim's date. */
  private claimDue(claim: Claim, person: Person): string {
    return claimDue(claim, this.rates(), gradeOn(person.grades, claim.date), this.floor.on(), this.late(),
      roundsBy(claim, this.claimsOf(person.id)));
  }

  /** The sum of the dues of the claims the person has that count (n/a ones skipped), 0.00 with none. A
   * person shows n/a when neither the grade they have on the sheet's today nor one they had on the date of a
   * claim that counts has a rate in force on the sheet's today, unless a claim that counts has a figure
   * (kept by a settlement or statement, or at a rate that applies on its date). Not held to the cap. */
  private uncappedDueTotal(person: Person): string {
    const counted = this.claimsOf(person.id).filter((c) => this.countsLive(c));
    const dues = counted.map((c) => this.claimDue(c, person)).filter((d) => d !== NO_RATE);
    const grades = [this.gradeToday(person), ...counted.map((c) => gradeOn(person.grades, c.date))];
    if (!grades.some((g) => g !== undefined && this.rateByGrade().has(g)) && dues.length === 0) return NO_RATE;
    return sumAmounts(dues);
  }

  /** The person's due-total held to the sheet's cap: the cap when the sum of their dues is above it; n/a is not
   * capped. */
  protected personDueTotal(person: Person): string {
    const total = this.uncappedDueTotal(person);
    const cap = this.cap.value();
    return total !== NO_RATE && cap !== null && hundredths(total) > hundredths(cap) ? cap : total;
  }

  /** What the sum of the person's dues is above the sheet's cap; 0.00 when it is not, or is n/a. */
  protected excess(person: Person): string {
    const total = this.uncappedDueTotal(person);
    if (total === NO_RATE) return '0.00';
    return fromHundredths(hundredths(total) - hundredths(this.personDueTotal(person)));
  }

  /** The person's claims that count and are overdue. */
  protected overdueOf(person: Person): Claim[] {
    const today = this.session.today();
    return this.claimsOf(person.id).filter((c) => this.countsLive(c) && isOverdue(c, today));
  }

  /** The sum of the dues of the person's overdue claims that count (n/a ones skipped), 0.00 with none. */
  protected overdueTotalOf(person: Person): string {
    return sumAmounts(
      this.overdueOf(person)
        .map((c) => this.claimDue(c, person))
        .filter((d) => d !== NO_RATE),
    );
  }

  /** The names of the person's patrons, sorted, comma and space separated. */
  protected patronNames(person: Person): string {
    return this.patronsOf(person)
      .map((p) => p.name)
      .sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
      .join(', ');
  }

  /** The person's backing: their patrons' due-totals added up (n/a ones skipped), 0.00 with no patrons. */
  protected backing(person: Person): string {
    return sumAmounts(this.patronsOf(person).map((p) => this.personDueTotal(p)).filter((d) => d !== NO_RATE));
  }

  private patronsOf(person: Person): Person[] {
    const byId = new Map(this.people().map((p) => [p.id, p]));
    return person.patronIds.map((id) => byId.get(id)).filter((p): p is Person => p !== undefined);
  }

  /** Name another person on the sheet as the person's patron. */
  protected addPatron(person: Person, patronId: string): void {
    this.patronError.set(null);
    this.personError.set(null);
    const sheetId = this.session.sheetId();
    if (!sheetId) return;
    if (!patronId) {
      this.patronError.set({ id: person.id, message: 'Choose a patron.' });
      return;
    }
    this.api.addPatron(sheetId, person.id, Number(patronId)).subscribe({
      next: (p) => {
        if (this.session.sheetId() === sheetId) this.people.update((ps) => ps.map((x) => (x.id === p.id ? p : x)));
      },
      error: (e: HttpErrorResponse) =>
        this.patronError.set({
          id: person.id,
          message:
            e.status === 409
              ? 'That person is already a patron.'
              : e.status === 422
                ? 'A person cannot be their own patron.'
                : e.status === 404
                  ? 'That person is no longer on this sheet.'
                  : 'Could not add that patron.',
        }),
    });
  }

  /** Whether a claim counts in the live totals: it counts, is not deferred on the sheet's today, and is not an OPEN
   * or PENDING claim dated within one of its person's holds and not bound by a statement. */
  private countsLive(claim: Claim): boolean {
    return (
      counts(claim) &&
      !isDeferred(claim, this.session.today()) &&
      !(isOpen(claim) && !bound(claim) && heldOn(this.holdsById().get(claim.personId) ?? [], claim.date))
    );
  }

  /** Whether a claim counts toward a period ending on a date: by the status it had at the end of that day, it is
   * OPEN, PENDING or SETTLED (one added after it is not), and the live rules leave it in: it is not deferred on
   * the sheet's today, and not OPEN or PENDING now, dated within one of its person's holds and not bound. */
  private countsAt(claim: Claim, end: string): boolean {
    const then = statusAt(claim, end);
    const openThen = then === 'OPEN' || then === 'PENDING';
    return (
      (openThen || then === 'SETTLED') &&
      !isDeferred(claim, this.session.today()) &&
      !(isOpen(claim) && !bound(claim) && heldOn(this.holdsById().get(claim.personId) ?? [], claim.date))
    );
  }

  protected rateSaved(rate: Rate): void {
    this.rates.update((rs) => [...rs.filter((r) => r.grade !== rate.grade || r.from !== rate.from), rate]);
  }

  protected periodSaved(period: Period): void {
    this.periods.update((ps) =>
      [...ps.filter((p) => p.id !== period.id), period].sort((a, b) => (a.from < b.from ? -1 : 1)),
}

/** Whether a claim is a correction: its amount is negative. */
export function isCorrection(claim: Claim): boolean {
  return claim.amount.startsWith('-');
}

/** A claim starts as DRAFT, is opened and then settled; one a clerk settles above the clerk limit is PENDING
 * until a steward approves it (SETTLED) or rejects it (OPEN again). A DRAFT, OPEN or PENDING claim can be voided. */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID';

/** The status changes a person can ask for on a claim; a rejection also needs a reason. */
export type ClaimAction = 'open' | 'settle' | 'approve' | 'void';

/** Whether a claim is still open: OPEN, or PENDING a steward. */
export function isOpen(claim: Claim): boolean {
  return claim.status === 'OPEN' || claim.status === 'PENDING';
}

/** Whether a claim is deferred on the sheet's today: it is still open and today has not reached the date it is
 * deferred until. Such a claim counts in no total, is not overdue and cannot be settled. */
export function isDeferred(claim: Claim, today: string | null): boolean {
  return isOpen(claim) && claim.deferredUntil !== null && today !== null && today < claim.deferredUntil;
}

/** Only OPEN, PENDING and SETTLED claims count toward what is claimed and due. */
export function counts(claim: Claim): boolean {
  return isOpen(claim) || claim.status === 'SETTLED';
}

/** The status a claim had at the end of a day (yyyy-mm-dd), as its status log records it (its lines are dated by
 * the sheet's today when each change was made): that of the last line on or before it; null when the claim was
 * added after it. A claim with no log (one there before the log was kept) has the status it has now. */
export function statusAt(claim: Claim, date: string): ClaimStatus | null {
  if (claim.statusLog.length === 0) return claim.status;
  return claim.statusLog.filter((l) => l.on <= date).at(-1)?.status ?? null;
}

/** Whether a claim goes by the figure its person's last statement bound it to: a PENDING claim is not bound, but
 * shows its live figure. */
export function bound(claim: Claim): boolean {
  return claim.stated && claim.status !== 'PENDING';
}

/** What a claim's late charge goes by: the sheet's today and its late percent in force on each of a claim's 30-day boundaries; and
 * the policy date its rounding goes by, the sheet's today when there is none. */
  claims: Claim[];
}

/** The sum of claim amounts with two decimals, added up in cents so no rounding creeps in. */
export function sumAmounts(amounts: string[]): string {
  return fromHundredths(amounts.reduce((sum, a) => sum + hundredths(a), 0n));
}

/** Amounts added up, leaving out the single highest and the single lowest when there are three or more. */
export function trimmedSum(amounts: string[]): string {
  if (amounts.length < 3) return sumAmounts(amounts);
  const sorted = amounts.map(hundredths).sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
  return fromHundredths(sorted.slice(1, -1).reduce((sum, a) => sum + a, 0n));
}

